<?php $host = "db"; $port = "5432"; $dbname = "example"; $username = "localuser"; $password = "cs4640LocalUser!"; try { $conn_string = "host=$host port=$port dbname=$dbname user=$username password=$password"; $conn = pg_connect($conn_string); if (!$conn) { throw new Exception("Failed to connect: " . pg_last_error()); } echo "Connected to database successfully<br>"; $sql = "CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE, email VARCHAR(100) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)"; $result = pg_query($conn, $sql); if (!$result) { throw new Exception("Error creating users table: " . pg_last_error($conn)); } echo "Users table created successfully!"; pg_close($conn); } catch(Exception $e) { echo "Error: " . $e->getMessage(); } ?>
